<script setup lang="ts">
import SDKIdentityPicker from "../components/SDKIdentityPicker.vue";
import {computed,onUnmounted,ref,watch} from 'vue';
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
import {api,type SnapshotInfo,type ModelConfig,type CatalogPage} from '../api';
import type {ComponentPlanDocument,ComponentPlanSnapshot,ComponentPlanVersion} from '../contracts';
import {componentDocument,componentView,canFreezeComponentPlan,checkedComponentVersion,componentOperationState,type ComponentPlanView,type ComponentVersionItem} from '../utils/component-plans';
import {useAuth} from '../composables/auth';
import ComponentScanLaunch from '../components/ComponentScanLaunch.vue';
import PageHeader from '../components/PageHeader.vue';
import Button from '../components/ui/Button.vue';
import Input from '../components/ui/Input.vue';
import Select from '../components/ui/Select.vue';
import CatalogPagination from '../components/CatalogPagination.vue';
import {confirm} from '../components/ui/confirm';
import {absoluteTime} from '../utils/time';

// Operate: an immutable source, an editable plan and inspectable validation.
// Existing neutral panes, compact controls and token-based geometry carry the UI.
const route=useRoute(),router=useRouter(),{canOperate}=useAuth();
const sourceId=ref(''),sourceSearch=ref(''),sources=ref<SnapshotInfo[]>([]),sourcePage=ref(1),sourceTotal=ref<number>(),sourceError=ref(''),sourcesBusy=ref(false);
const plans=ref<ComponentPlanSnapshot[]>([]),plansPage=ref(1),plansTotal=ref<number>(),plansError=ref(''),plansBusy=ref(false);
const view=ref<ComponentPlanView|null>(null),loadError=ref(''),busy=ref(false),actionError=ref(''),action=ref(''),notice=ref(''),newTitle=ref('组件计划');
const draft=ref<ComponentPlanDocument>({components:[]}),rawMode=ref(false),rawText=ref(''),savedText=ref(''),rawOpen=ref(false);
const versions=ref<CatalogPage<ComponentVersionItem>|null>(null),versionError=ref(''),versionBusy=ref(false),version=ref<ComponentPlanVersion|null>(null);
const models=ref<ModelConfig[]>([]),modelError=ref(''),modelId=ref(''),acknowledge=ref(false),coveragePage=ref(1);
let generation=0,sourceGeneration=0,planGeneration=0,versionGeneration=0,searchTimer:ReturnType<typeof setTimeout>|undefined;
const id=computed(()=>typeof route.params.id==='string'?route.params.id:''),text=computed(()=>JSON.stringify(draft.value));
const dirty=computed(()=>!!view.value&&(rawMode.value?rawText.value!==JSON.stringify(view.value.plan.document,null,2):text.value!==savedText.value));
const inFlight=computed(()=>['pending','claimed','scanning','cancel_requested'].includes(view.value?.operationStatus??''));
const canFreeze=computed(()=>!!view.value&&canFreezeComponentPlan(view.value)&&!dirty.value&&!action.value);
const stale=computed(()=>!!view.value?.result&&view.value.result.operation.revision!==view.value.plan.revision);
const coverage=computed(()=>view.value?.result?.coverage),missing=computed(()=>coverage.value?.uncoveredPaths.slice((coveragePage.value-1)*50,coveragePage.value*50)??[]);
const sourceOptions=computed(()=>sources.value.map(s=>({value:String(s.id),label:`#${s.id} ${s.originalFilename} · ${s.fileCount} 文件`})));
const versionMatchesDraft=computed(()=>version.value?.revision===view.value?.plan.revision);

function fill(plan:ComponentPlanSnapshot){draft.value=structuredClone(plan.document);savedText.value=JSON.stringify(plan.document);rawText.value=JSON.stringify(plan.document,null,2);rawMode.value=false;coveragePage.value=1;}
async function loadSources(page=1){const current=++sourceGeneration;sourcesBusy.value=true;sourceError.value='';try{const list=await api.snapshotPage({page,q:sourceSearch.value});const pinned=sourceId.value?await api.snapshotPage({id:Number(sourceId.value)}):null;if(current!==sourceGeneration)return;sources.value=list.items;if(pinned?.items[0]&&!sources.value.some(s=>String(s.id)===sourceId.value))sources.value.unshift(pinned.items[0]);sourcePage.value=list.page;sourceTotal.value=list.total;}catch(e){if(current===sourceGeneration)sourceError.value=(e as Error).message}finally{if(current===sourceGeneration)sourcesBusy.value=false}}
async function loadPlans(page=1){const current=++planGeneration;plansBusy.value=true;plansError.value='';try{if(!sourceId.value){plans.value=[];plansTotal.value=undefined;return}const list=await api.componentPlans(Number(sourceId.value),page);if(current!==planGeneration)return;plans.value=list.items;plansTotal.value=list.total;plansPage.value=list.page;}catch(e){if(current===planGeneration)plansError.value=(e as Error).message}finally{if(current===planGeneration)plansBusy.value=false}}
async function load(quiet=false){const current=++generation;if(!id.value){view.value=null;return}if(!quiet){busy.value=true;loadError.value='';version.value=null}try{const next=componentView(await api.componentPlan(id.value));if(current!==generation)return;if(quiet&&view.value&&next.plan.revision!==view.value.plan.revision&&dirty.value){actionError.value='服务器草稿已更新，本地修改已保留。请复制本地计划后重新读取。';return}const reset=!view.value||view.value.plan.id!==next.plan.id||(!dirty.value&&view.value.plan.revision!==next.plan.revision);view.value=next;sourceId.value=next.plan.source.snapshotId;if(reset||!quiet)fill(next.plan);if(!quiet){await Promise.all([loadSources(),loadPlans(),loadVersions()]);}}catch(e){if(current===generation)loadError.value='计划读取失败：'+(e as Error).message}finally{if(current===generation)busy.value=false}}
async function loadVersions(page=1){const current=++versionGeneration;if(!id.value)return;versionBusy.value=true;versionError.value='';try{const list=await api.componentVersions(id.value,page);if(current===versionGeneration)versions.value=list}catch(e){if(current===versionGeneration)versionError.value=(e as Error).message}finally{if(current===versionGeneration)versionBusy.value=false}}
async function inspectVersion(n:number){const current=++versionGeneration;versionBusy.value=true;versionError.value='';try{const next=await api.componentVersion(id.value,n);if(current===versionGeneration&&view.value)version.value=checkedComponentVersion(next,view.value.plan)}catch(e){if(current===versionGeneration)versionError.value=(e as Error).message}finally{if(current===versionGeneration)versionBusy.value=false}}
async function perform(name:string,work:()=>Promise<void>){if(action.value)return;const currentId=id.value;action.value=name;actionError.value='';notice.value='';try{await work()}catch(e){if(currentId===id.value)actionError.value=(e as Error).message}finally{action.value=''}}
async function create(){if(!canOperate.value||!sourceId.value)return;await perform('create',async()=>{const next=await api.createComponentPlan({snapshotId:Number(sourceId.value),title:newTitle.value,document:{components:[{name:'全部源码',paths:['.']}]}});await router.push('/component-plans/'+next.id);});}
async function save(){if(!view.value)return;await perform('save',async()=>{const document=componentDocument(rawMode.value?rawText.value:JSON.stringify(draft.value));const next=await api.saveComponentPlan(id.value,view.value!.plan.revision,document);if(next.id!==id.value)return;fill(next);view.value={...view.value!,plan:next};notice.value='草稿已保存，需要重新校验后才能冻结。';await Promise.all([load(true),loadPlans()]);});}
const sdkIdentityId=ref('');
async function operation(kind:'normalize'|'suggest'){if(!view.value||dirty.value)return;await perform(kind,async()=>{await api.componentOperation(id.value,{revision:view.value!.plan.revision,kind,...(kind==='suggest'?{...(sdkIdentityId.value?{sdkIdentityId:sdkIdentityId.value}:{}),modelConfigId:Number(modelId.value),acknowledgeUnknownCost:acknowledge.value}:{})});await load(true);});}
async function cancel(){const task=view.value?.operationTaskId;if(!task)return;await perform('cancel',async()=>{await api.cancelScan(Number(task));await load(true)});}
async function applySuggestion(){if(!view.value?.resultSha256||!view.value.operationTaskId)return;await perform('apply',async()=>{const next=await api.applyComponentSuggestion(id.value,{revision:view.value!.plan.revision,taskId:view.value!.operationTaskId!,resultSha256:view.value!.resultSha256!});fill(next);view.value={...view.value!,plan:next};notice.value='已将 SDK 建议保存为新草稿；请审阅并执行本地校验。';await Promise.all([load(true),loadPlans()]);});}
async function freeze(){if(!canFreeze.value||!view.value)return;if(!await confirm({title:'确认并冻结组件计划',body:`将草稿 r${view.value.plan.revision} 确认为不可修改的新版本，绑定当前源码哈希与校验执行。此操作不会启动组件扫描。`}))return;await perform('freeze',async()=>{const frozen=await api.freezeComponentPlan(id.value,{revision:view.value!.plan.revision,taskId:view.value!.operationTaskId!,resultSha256:view.value!.resultSha256!});version.value=checkedComponentVersion(frozen,view.value!.plan);notice.value=`已冻结版本 v${frozen.version}，未启动扫描。`;await loadVersions();});}
function toggleRaw(){if(!rawMode.value)rawText.value=JSON.stringify(draft.value,null,2);else{try{draft.value=componentDocument(rawText.value)}catch(e){actionError.value=(e as Error).message;return}}rawMode.value=!rawMode.value;}
function changePaths(index:number,event:Event){const c=draft.value.components[index];if(c)c.paths=(event.target as HTMLTextAreaElement).value.split('\n').filter(v=>v.length>0)}
function focusComponent(index:number){document.getElementById('component-paths-'+index)?.focus()}
function downloadVersion(){if(!version.value)return;const blob=new Blob([JSON.stringify(version.value,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`component-plan-${id.value}-v${version.value.version}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function loadModels(){modelError.value='';try{models.value=await api.listModelConfigs()}catch(e){modelError.value=(e as Error).message}}
watch(()=>route.fullPath,()=>{generation++;view.value=null;version.value=null;loadError.value='';actionError.value='';notice.value='';sourceId.value=id.value?'':String(route.query.snapshotId??'');void(id.value?load():Promise.all([loadSources(),loadPlans()]));},{immediate:true});
watch(sourceSearch,()=>{clearTimeout(searchTimer);sourceGeneration++;searchTimer=setTimeout(()=>void loadSources(),250)});
watch(sourceId,(next,old)=>{if(next!==old)void loadPlans()});
const poll=setInterval(()=>{if(inFlight.value&&!action.value)void load(true)},1500);void loadModels();
onBeforeRouteUpdate(async()=>!dirty.value||await confirm({title:'离开当前计划',body:'当前草稿尚未保存，是否放弃本地修改并切换计划？'}));
onBeforeRouteLeave(async()=>!dirty.value||await confirm({title:'保留当前计划修改',body:'当前草稿尚未保存。离开会丢失本地修改，是否仍然离开？'}));
onUnmounted(()=>{generation++;planGeneration++;sourceGeneration++;versionGeneration++;clearInterval(poll);clearTimeout(searchTimer)});
</script>

<template>
 <div class="component-workspace">
  <PageHeader title="组件计划" description="绑定不可变源码，审阅组件边界，再确认版本。规划与确认不会启动组件扫描。"><a v-if="id" class="mobile-plan-jump" href="#component-plan-editor">跳到当前计划</a><RouterLink to="/assets">返回资产</RouterLink></PageHeader>
  <div v-if="loadError" role="alert" class="request-error">{{loadError}}<Button variant="outline" @click="load()">重新读取计划</Button></div>
  <p v-if="busy" role="status">正在读取计划、源码身份与冻结版本…</p>
  <div class="plan-panes">
   <aside class="plan-navigation" aria-label="源码与组件计划">
    <h2>源码快照</h2><label for="plan-source-search">搜索全部源码快照</label><Input id="plan-source-search" v-model="sourceSearch" placeholder="文件名或哈希" :disabled="!!id" />
    <Select v-model="sourceId" :options="sourceOptions" placeholder="选择不可变源码快照" aria-label="组件计划源码快照" :disabled="!!id||sourcesBusy"/>
    <p v-if="sourceError" role="alert">{{sourceError}}<Button variant="ghost" @click="loadSources()">重读源码列表</Button></p>
    <CatalogPagination v-if="!id" label="计划源码分页" :page="sourcePage" :total="sourceTotal" :loading="sourcesBusy" @change="loadSources"/>
    <h2>快照中的计划</h2><p v-if="plansError" role="alert">{{plansError}}<Button variant="ghost" @click="loadPlans()">重读计划列表</Button></p>
    <ul class="plan-list" aria-label="组件计划列表"><li v-for="p in plans" :key="p.id"><RouterLink :to="'/component-plans/'+p.id" :aria-current="id===p.id?'page':undefined">{{p.title}}<span>草稿 r{{p.revision}}</span></RouterLink></li></ul>
    <p v-if="!plansBusy&&!plans.length">{{sourceId?'此快照尚无组件计划。':'选择源码后可管理其组件计划。'}}</p>
    <CatalogPagination label="组件计划分页" :page="plansPage" :total="plansTotal" :loading="plansBusy" @change="loadPlans"/>
    <form v-if="canOperate&&sourceId" class="create-plan" @submit.prevent="create"><label for="plan-title">新计划名称</label><Input id="plan-title" v-model="newTitle" maxlength="200"/><Button type="submit" variant="outline" :disabled="!!action||!newTitle.trim()">新建人工计划</Button><p>从完整源码范围开始编辑，不调用模型。</p></form>
   </aside>
   <section v-if="view&&!busy" id="component-plan-editor" tabindex="-1" class="plan-editor" aria-label="组件计划编辑与确认">
    <header class="plan-header"><h2>{{view.plan.title}}</h2><span>草稿 r{{view.plan.revision}} · {{view.plan.origin==='manual'?'人工编辑':'源于 SDK 建议'}}</span></header>
    <dl class="plan-source"><div><dt>源码快照</dt><dd>#{{view.plan.source.snapshotId}}</dd></div><div><dt>内容 SHA-256</dt><dd class="mono">{{view.plan.source.contentHash}}</dd></div><div v-if="view.plan.source.headCommit"><dt>冻结 HEAD</dt><dd class="mono">{{view.plan.source.headCommit}}</dd></div></dl>
    <p v-if="view.plan.source.headCommit" class="plan-note">组件规划检查冻结 HEAD 的完整源码，独立于 base/head 差异审计范围。</p>
    <div v-if="actionError" role="alert" class="request-error">{{actionError}}</div><p v-if="notice" role="status" class="plan-note">{{notice}}</p>
    <div class="plan-toolbar"><Button v-if="canOperate" variant="outline" :disabled="!!action||rawMode||draft.components.length>=128" @click="draft.components.push({name:'新组件',paths:[]})">添加组件</Button><Button variant="ghost" :disabled="!!action" @click="toggleRaw">{{rawMode?'返回组件表格':canOperate?'编辑计划 JSON':'查看计划 JSON'}}</Button><Button v-if="canOperate" :disabled="!dirty||!!action" @click="save">{{action==='save'?'保存中…':'保存草稿'}}</Button><Button variant="ghost" :disabled="!!action" @click="load()">{{dirty?'放弃本地修改并重新读取':'重新读取计划'}}</Button></div>
    <p v-if="dirty" role="status" class="plan-note">有未保存修改。保存后，旧校验不会用于确认此草稿。</p>
    <template v-if="rawMode"><label for="component-plan-json">组件计划 JSON</label><textarea id="component-plan-json" v-model="rawText" class="raw-editor mono" :readonly="!canOperate" spellcheck="false"/></template>
    <div v-else class="component-table-scroll"><table class="component-table"><thead><tr><th scope="col">组件</th><th scope="col">源码路径 · 每行一个</th><th scope="col"><span class="sr-only">操作</span></th></tr></thead><tbody><tr v-for="(c,index) in draft.components" :key="index"><td><label class="sr-only" :for="'component-name-'+index">组件 {{index+1}} 名称</label><Input :id="'component-name-'+index" v-model="c.name" maxlength="200" :disabled="!canOperate||!!action"/></td><td><label class="sr-only" :for="'component-paths-'+index">组件 {{index+1}} 路径</label><textarea :id="'component-paths-'+index" :value="c.paths.join('\n')" :readonly="!canOperate||!!action" rows="2" class="mono" spellcheck="false" @input="changePaths(index,$event)"/></td><td><Button v-if="canOperate" variant="ghost" :disabled="!!action||draft.components.length<=1" :aria-label="'移除组件 '+(index+1)" @click="draft.components.splice(index,1)">移除</Button></td></tr></tbody></table></div>
    <p class="plan-note">根目录使用 <code>.</code>。目录边界包含其全部源码；重叠、遗漏、空组件和重名会阻止确认。特殊文件名可通过 JSON 编辑。</p>
    <section class="plan-section" aria-label="计划校验与确认"><h3>路径校验与确认</h3><div class="plan-toolbar"><Button v-if="canOperate" variant="outline" :disabled="dirty||!!action||inFlight" @click="operation('normalize')">规范化并检查覆盖</Button><Button v-if="canOperate" :disabled="!canFreeze||versionMatchesDraft" @click="freeze">确认并冻结版本</Button><Button v-if="canOperate&&inFlight" variant="outline" :disabled="!!action||view.operationStatus==='cancel_requested'" @click="cancel">取消当前操作</Button></div>
     <p class="plan-note">本地校验调用 SDK normalizeComponentPlan，不调用模型，费用为已知零。确认后版本不可修改，后续编辑生成新草稿修订。</p>
     <p v-if="view.operationTaskId" role="status">{{componentOperationState(view.operationStatus)}} · <RouterLink :to="'/scans/'+view.operationTaskId">查看执行 #{{view.operationTaskId}}</RouterLink><span v-if="view.operation"> · {{view.operation.kind==='suggest'?'费用未知，不能视为零':'本地校验 · 费用 $0'}}</span></p>
     <p v-if="stale" role="status" class="plan-note">下面是旧草稿 r{{view.result?.operation.revision}} 的结果，不能确认或覆盖当前草稿。</p>
     <p v-if="!view.result&&view.operationError" role="alert" class="request-error">{{view.operationError}}</p>
     <p v-if="view.result?.error" role="alert" class="request-error">{{view.result.error.code}}：{{view.result.error.message}}</p>
     <div v-if="coverage" class="plan-check"><p>{{coverage.valid?'路径校验通过':'范围需要调整'}} · 已覆盖 {{coverage.coveredFileCount}} / {{coverage.fileCount}} 个文件 · {{coverage.overlapCount}} 处重叠</p>
      <p v-for="(overlap,i) in coverage.overlaps" :key="i" class="plan-note"><button type="button" @click="focusComponent(overlap.leftComponent)">组件 {{overlap.leftComponent+1}}</button> <code>{{overlap.leftPath}}</code> 与 <button type="button" @click="focusComponent(overlap.rightComponent)">组件 {{overlap.rightComponent+1}}</button> <code>{{overlap.rightPath}}</code> 重叠</p><p v-if="coverage.overlapCount>coverage.overlaps.length">共 {{coverage.overlapCount}} 处重叠，界面列出前 {{coverage.overlaps.length}} 处。</p>
      <p v-if="coverage.emptyComponents.length">没有覆盖文件的组件：{{coverage.emptyComponents.map(i=>i+1).join('、')}}</p><p v-if="coverage.duplicateNames.length">重名组件：{{coverage.duplicateNames.join('、')}}</p>
      <section v-if="coverage.uncoveredPaths.length" aria-label="遗漏文件"><h4>遗漏文件</h4><ul class="missing-files"><li v-for="p in missing" :key="p" class="mono">{{p}}</li></ul><CatalogPagination label="遗漏文件分页" :page="coveragePage" :total="coverage.uncoveredPaths.length" @change="coveragePage=$event"/></section>
     </div>
     <button v-if="view.result" type="button" class="raw-link" :aria-expanded="rawOpen" @click="rawOpen=!rawOpen">{{rawOpen?'收起':'查看'}}原始规划与校验结果</button><pre v-if="rawOpen" class="raw-result mono">{{JSON.stringify(view.result,null,2)}}</pre>
    </section>
    <section class="plan-section" aria-label="SDK 自动规划建议"><h3>SDK 自动规划建议</h3><p class="plan-note">生成建议会调用模型。SDK 的 planComponents 没有费用回调或费用上限；费用保持未知。建议须人工采用、审阅并重新校验后才能冻结。</p>
     <p v-if="modelError" role="alert">模型配置读取失败：{{modelError}}<Button variant="ghost" @click="loadModels">重读模型配置</Button></p>
     <label for="component-model">规划模型</label><Select id="component-model" aria-label="规划模型" v-model="modelId" :options="models.map(m=>({value:String(m.id),label:m.name+' · '+m.model}))" placeholder="选择规划模型" :disabled="!canOperate||!!action||inFlight"/>
     <label class="cost-ack"><input v-model="acknowledge" type="checkbox" :disabled="!canOperate||!!action||inFlight"/>我知悉自动规划会调用模型，费用未知且不受扫描预算上限控制</label>
     <SDKIdentityPicker v-if="canOperate" v-model="sdkIdentityId" :native="models.find(m=>String(m.id)===modelId)?.provider==='openai'" :disabled="!!action||inFlight"/>
     <div class="plan-toolbar"><Button v-if="canOperate" variant="outline" :disabled="dirty||!!action||inFlight||!modelId||!acknowledge||!!modelError" @click="operation('suggest')">生成组件建议</Button><Button v-if="canOperate&&view.result?.operation.kind==='suggest'&&!view.result.error" variant="outline" :disabled="dirty||stale||!!action||inFlight" @click="applySuggestion">采用建议为新草稿</Button></div>
     <details v-if="view.result?.operation.kind==='suggest'&&view.result.document"><summary>查看 SDK 建议 · 未确认</summary><pre class="raw-result mono">{{JSON.stringify(view.result.document,null,2)}}</pre></details>
    </section>
    <section class="plan-section" aria-label="冻结版本"><h3>冻结版本</h3><p v-if="versionError" role="alert" class="request-error">{{versionError}}<Button variant="ghost" @click="loadVersions()">重读版本列表</Button></p><p v-if="versions&&!versions.items.length">尚未确认版本。先保存草稿并完成本地校验。</p>
     <ul class="version-list"><li v-for="v in versions?.items" :key="v.version"><Button variant="ghost" :disabled="versionBusy" @click="inspectVersion(v.version)">查看冻结版本 v{{v.version}}</Button><span>草稿 r{{v.revision}} · {{absoluteTime(v.confirmedAt)}}</span></li></ul><CatalogPagination label="冻结版本分页" :page="versions?.page" :total="versions?.total" :loading="versionBusy" @change="loadVersions"/>
     <section v-if="version" class="frozen-version" aria-label="冻结版本详情"><h4>版本 v{{version.version}} · 不可修改</h4><dl><div><dt>确认人 / 时间</dt><dd>#{{version.confirmedBy}} · {{absoluteTime(version.confirmedAt)}}</dd></div><div><dt>版本 SHA-256</dt><dd class="mono">{{version.sha256}}</dd></div><div><dt>校验执行</dt><dd><RouterLink :to="'/scans/'+version.validationExecution.taskId">#{{version.validationExecution.taskId}} / {{version.validationExecution.attempt}}</RouterLink></dd></div></dl><Button variant="outline" @click="downloadVersion">下载冻结计划 JSON</Button><pre class="raw-result mono">{{JSON.stringify(version.document,null,2)}}</pre><ComponentScanLaunch :key="version.sha256" :version="version" :models="models"/></section>
    </section>
   </section>
   <section v-else-if="!busy&&!loadError" class="plan-empty"><h2>选择或创建组件计划</h2><p>计划保留源码身份、编辑修订、SDK 建议及人工确认的版本。没有真实数据时不会填入模拟组件。</p></section>
  </div>
 </div>
</template>

